#[inductive(initialize)]
fn initialize_inductive(post: Self, backing_cells: Seq<CellId>, storage: Map<nat, cell::PointsTo<T>>) {
    assert forall|i: nat|
        0 <= i && i < post.len() implies post.valid_storage_at_idx(i)
    by {
        // We assume the initialize precondition holds:
        // (forall|i: nat| 0 <= i && i < backing_cells.len() ==>
        //     #[trigger] storage.dom().contains(i)
        //     && storage.index(i).id() == backing_cells.index(i as int)
        //     && storage.index(i).is_uninit())

        assert(0 <= i && i < post.len());
        assert(backing_cells.len() == post.len());
        assert(storage === post.storage);
        assert(backing_cells === post.backing_cells);
        assert(0 <= i && i < backing_cells.len());

        // Explicitly instantiate the precondition for our specific i:
        assert(#[trigger] storage.dom().contains(i));
        assert(post.storage.dom().contains(i));

        assert(storage.index(i).id() == backing_cells.index(i as int));
        assert(post.storage.index(i).id() == post.backing_cells.index(i as int));

        // At initialization:
        assert(post.head == 0);
        assert(post.tail == 0);
        assert(post.producer == ProducerState::Idle(0));
        assert(post.consumer == ConsumerState::Idle(0));

        // Therefore nothing is checked out:
        assert(!post.is_checked_out(i));

        // And the active range is empty (head == tail):
        assert(!post.in_active_range(i));

        // So the cell should be uninit:
        assert(post.storage.index(i).is_uninit());

        // This establishes post.valid_storage_at_idx(i) 
    }
}

